function open(name) {
  console.log("open " + name);
  return {
    [Symbol.dispose]() {
      console.log("close " + name);
    },
  };
}

try {
  using first = open("first");
  using nothing = null;
  using second = { name: "second" };
  console.log("body");
} catch (error) {
  console.log(error.name);
}
